# Rangos razonables para los parametros de la demostracion (hallazgo H-01 del
# EVI-01). Un transformador de distribucion trabaja con 1 a 66 kV en el
# primario y 100 a 1.000 V en el secundario. Si el parametro no existe, no se
# hace nada; el Administrador puede ajustar los rangos despues.
RANGOS = {
    "tension_prim": (Decimal("1"), Decimal("66")),
    "tension_sec": (Decimal("100"), Decimal("1000")),
}


def cargar_rangos(apps, schema_editor):
    ParametroTecnico = apps.get_model("catalogo", "ParametroTecnico")
    for codigo, (minimo, maximo) in RANGOS.items():
        ParametroTecnico.objects.filter(codigo=codigo, valor_minimo__isnull=True,
                                        valor_maximo__isnull=True).update(
            valor_minimo=minimo, valor_maximo=maximo)
    # La potencia define el modelo: una solicitud con modelo no puede pedir otra
    ParametroTecnico.objects.filter(codigo="potencia_kva").update(fija_el_modelo=True)


